def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    p = prev_offer.shape[1]
    rate = np.where(prev_offer > 0.5, prev_contrib / np.maximum(prev_offer, 1e-12), 0.5)
    if "rep" not in mem:
        mem["rep"] = np.full(prev_offer.shape, 0.5)
    mem["rep"] = 0.8 * mem["rep"] + 0.2 * rate
    weight = mem["rep"] + 0.1
    share = weight / weight.sum(axis=1, keepdims=True)
    budget = 0.5 * pool[:, None]
    return np.maximum(budget * share, np.minimum(1.0, pool[:, None] / p))

def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    G, p = prev_offer.shape
    if t == 1:
        mem['rate'] = np.full((G, p), 0.5)
    else:
        made = prev_offer > 0
        new_rate = np.where(made, prev_contrib / np.maximum(prev_offer, 1e-12), mem['rate'])
        mem['rate'] = 0.7 * mem['rate'] + 0.3 * new_rate

    weight = 0.5 + mem['rate']
    share = weight / weight.sum(axis=1, keepdims=True)

    budget = np.minimum(pool, 0.5 * cap) [:, None] * share
    return np.maximum(budget, 1.0)

def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    G, p = prev_offer.shape
    if t == 1:
        mem["rel"] = np.full((G, p), 0.5)
    else:
        frac = np.where(prev_offer > 0, prev_contrib / np.maximum(prev_offer, 1e-9), 0.5)
        mem["rel"] = 0.8 * mem["rel"] + 0.2 * frac
    rel = mem["rel"] + 0.05
