    budget = 0.35 * pool[:, None]
    offers = budget * weights
    return np.maximum(offers, 1.0)

def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    G, p = prev_offer.shape
    if t == 1:
        mem['trust'] = np.full((G, p), 0.5)
    else:
        frac = np.where(prev_offer > 0, prev_contrib / np.maximum(prev_offer, 1e-9), 0.5)
        mem['trust'] = 0.8 * mem['trust'] + 0.2 * frac

    trust = mem['trust']
    # weight equal shares more when reservoir is low, proportional-to-trust more when high
    w = (pool / cap)[:, None] ** 8
    share = w / p + (1 - w) * (trust / np.maximum(trust.sum(axis=1, keepdims=True), 1e-9))
    offers = pool[:, None] * share
    return np.maximum(offers, 0.0)
